from z3 import *
n=12
f=Function('f', IntSort(), IntSort(), IntSort())
s=Solver()
s.set('timeout', 55000)
# variables as applications f(i,j)
x=[[f(i,j) for j in range(n)] for i in range(n)]
# domains
for i in range(n):
    for j in range(n):
        s.add(x[i][j]>=0, x[i][j]<n)
# latin
for i in range(n):
    s.add(Distinct(x[i]))
for j in range(n):
    s.add(Distinct([x[i][j] for i in range(n)]))
# diag
for i in range(n): s.add(x[i][i]==i)
# normalize row0
for j in range(n): s.add(x[0][j]==j)
# QG3
for i in range(n):
    for j in range(n):
        s.add(f(x[i][j], x[j][i]) == i)
print('constraints', len(s.assertions()))
res=s.check()
print(res)
if res==sat:
    m=s.model()
    grid=[]
    for i in range(n):
        row=[]
        for j in range(n):
            val=m.eval(x[i][j], model_completion=True).as_long()
            row.append(val); grid.append(val)
        print(row)
    print(grid)
else:
    print(s.reason_unknown())

