from pysat.solvers import Glucose3, Cadical153, Minisat22
n=12
def var(i,j,v): return (i*n+j)*n+v+1
clauses=[]
# exactly one per cell
for i in range(n):
  for j in range(n):
    clauses.append([var(i,j,v) for v in range(n)])
    for v in range(n):
      for w in range(v+1,n): clauses.append([-var(i,j,v),-var(i,j,w)])
# each value exactly once per row/col: at most (at least follows from cells? not exactly for each value; add at least too)
for i in range(n):
  for v in range(n):
    clauses.append([var(i,j,v) for j in range(n)])
    for j1 in range(n):
      for j2 in range(j1+1,n): clauses.append([-var(i,j1,v),-var(i,j2,v)])
for j in range(n):
  for v in range(n):
    clauses.append([var(i,j,v) for i in range(n)])
    for i1 in range(n):
      for i2 in range(i1+1,n): clauses.append([-var(i1,j,v),-var(i2,j,v)])
# diag
for i in range(n): clauses.append([var(i,i,i)])
# QG3 implications: xij=a & xji=b -> xab=i
# Also if a/b invalid? all values. For all i,j,a,b.
for i in range(n):
  for j in range(n):
    for a in range(n):
      for b in range(n):
        clauses.append([-var(i,j,a), -var(j,i,b), var(a,b,i)])
# symmetry
clauses.append([var(0,1,2)]); clauses.append([var(1,0,3)]); # implies [2,3]=0,[3,2]=1
print('vars', n*n*n, 'clauses', len(clauses))
# try solver
for SolverCls in [Cadical153, Glucose3, Minisat22]:
    try:
        s=SolverCls(bootstrap_with=clauses)
        print('solver',SolverCls)
        sat=s.solve()
        print('sat',sat)
        if sat:
            model=set(l for l in s.get_model() if l>0)
            grid=[]
            for i in range(n):
                row=[]
                for j in range(n):
                    vals=[v for v in range(n) if var(i,j,v) in model]
                    row.append(vals[0]); grid.append(vals[0])
                print(row)
            print(grid)
            raise SystemExit
        s.delete()
    except Exception as e:
        print('err',e)

